/**
 * FINANCIAL ESPIONAGE LEDGER - DETERMINISTIC DEMO RECORDS + THE 20 METRICS
 *
 * WHAT IS REAL AND WHAT IS NOT
 * ----------------------------
 * Real: institution names, county coverage, branch counts and deposit totals - all
 * from the FDIC Summary of Deposits 2025 response for Georgia (see
 * georgiaFinancialInstitutions.ts). Live rows in the UI come from the dashboard's own
 * OSINT event stream and carry the real headline.
 *
 * Not real: the 2,023 ledger records below. They are generated by this module from a
 * fixed hash of the institution id, so they are stable across reloads and identical on
 * every device. They are NOT observations of, intrusions into, or claims about any
 * bank, account, login or person. Every card built from them is stamped DEMO in the UI
 * and the section carries a disclosure. Account, login and host identifiers are
 * fabricated masked placeholders.
 *
 * The 20 metrics are a fixed financial-signal model over the real institution figures
 * plus a deterministic pseudo-signal. They are illustrative measures, not regulatory
 * filings, not audited figures, and not loss estimates for any institution.
 */

import { FINANCIAL_INSTITUTIONS, type FinancialInstitution } from '../data/georgiaFinancialInstitutions.ts';

export type Severity = 'critical' | 'high' | 'medium';

export interface AnomalyRecord {
  id: string;
  institutionId: string;
  institutionName: string;
  severity: Severity;
  archetype: string;
  title: string;
  vector: string;
  /** Minutes before "now" that the record is stamped. */
  offsetMinutes: number;
  systems: string[];
  logins: string[];
  accounts: string[];
  demo: true;
}

/** A real headline from the live OSINT stream, attached to an institution. */
export interface LiveRecord {
  id: string;
  institutionId: string | null;
  institutionName: string | null;
  severity: Severity;
  title: string;
  source: string;
  ts: string;
  demo: false;
}

export const LEDGER_SIZE = 2023;

/* -------------------------------------------------------------------------- */
/* deterministic hashing                                                       */
/* -------------------------------------------------------------------------- */

function fnv1a(input: string): number {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i += 1) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash >>> 0;
}

/** Uniform [0,1) from a seed string. */
export function seedUnit(seed: string): number {
  return fnv1a(seed) / 0x100000000;
}

function pick<T>(items: readonly T[], seed: string): T {
  return items[fnv1a(seed) % items.length];
}

function pickMany<T>(items: readonly T[], count: number, seed: string): T[] {
  const out: T[] = [];
  const used = new Set<number>();
  for (let i = 0; out.length < Math.min(count, items.length) && i < items.length * 3; i += 1) {
    const index = fnv1a(`${seed}:${i}`) % items.length;
    if (used.has(index)) continue;
    used.add(index);
    out.push(items[index]);
  }
  return out;
}

