/* -------------------------------------------------------------------------- */
/* metric model - 20 measures per anomaly                                      */
/* -------------------------------------------------------------------------- */

export interface FinancialMetric {
  key: string;
  label: string;
  display: string;
  /** 0..1 normalised level, used only for the bar under the value. */
  level: number;
  tone: 'risk' | 'watch' | 'steady';
}

function usd(value: number, digits = 2): string {
  if (value >= 1e9) return `$${(value / 1e9).toFixed(digits)}B`;
  if (value >= 1e6) return `$${(value / 1e6).toFixed(digits)}M`;
  if (value >= 1e3) return `$${(value / 1e3).toFixed(0)}K`;
  return `$${value.toFixed(0)}`;
}

const clamp01 = (v: number) => (v < 0 ? 0 : v > 1 ? 1 : v);
const tone = (level: number): FinancialMetric['tone'] => (level >= 0.66 ? 'risk' : level >= 0.33 ? 'watch' : 'steady');

/**
 * The 20 recommended financial metrics, computed for one anomaly.
 * Every input is real institution scale (deposits, branches, counties) combined with a
 * deterministic signal for this anomaly id, so the same anomaly always shows the same
 * numbers. Illustrative measures - see the module header.
 */
export function metricsFor(inst: FinancialInstitution, anomalyId: string): FinancialMetric[] {
  const s = (key: string) => seedUnit(`${anomalyId}:${key}`);
  const deposits = inst.depositsUsd;
  const branches = Math.max(1, inst.branches);
  const counties = Math.max(1, inst.countyCount);

  const exposure = deposits * (0.00035 + 0.0022 * s('exposure'));
  const exposureRatio = clamp01((exposure / Math.max(1, deposits)) * 100) ;
  const wireVelocity = 90 + branches * 11 + s('wirevel') * 640;
  const wireAtRisk = exposure * (0.18 + 0.55 * s('wireatrisk'));
  const achReturn = 0.4 + s('achret') * 3.4;
  const achExceptions = 3 + Math.round(s('achexc') * (18 + branches * 1.6));
  const latency = 180 + Math.round(s('latency') * 2400);
  const duplicates = Math.round(s('dupes') * Math.max(2, branches * 0.8));
  const dormant = Math.round(s('dormant') * Math.max(2, counties * 1.4));
  const cnp = 1800 + s('cnp') * 42000;
  const callbacks = Math.round(s('callback') * Math.max(2, branches * 0.35));
  const offWindow = Math.round(s('offwin') * Math.max(1, branches * 0.22));
  const mfaFail = 6 + Math.round(s('mfa') * (40 + branches * 1.2));
  const sessions = 2 + Math.round(s('sessions') * Math.max(4, branches * 0.9));
  const sanctions = Math.round(s('sanctions') * Math.max(1, counties * 0.4));
  const nsf = 0.8 + s('nsf') * 4.6;
  const rateSens = 40 + Math.round(s('rate') * 260);
  const lcr = 2 + s('lcr') * 22;
  const collateral = 1 + s('coll') * 14;
  const recon = Math.round(s('recon') * Math.max(2, branches * 0.6));

  const rows: Array<Omit<FinancialMetric, 'tone' | 'level'> & { level: number }> = [
    { key: 'deposit-exposure', label: 'Deposit exposure', display: usd(exposure), level: clamp01(s('exposure') * 0.9 + 0.15) },
    { key: 'exposure-ratio', label: 'Exposure vs deposits', display: `${exposureRatio.toFixed(2)}%`, level: clamp01(exposureRatio * 6) },
    { key: 'wire-velocity', label: 'Wire room velocity', display: `${wireVelocity.toFixed(0)}/day`, level: clamp01(wireVelocity / 900) },
    { key: 'wire-at-risk', label: 'Wire value at risk', display: usd(wireAtRisk), level: clamp01(s('wireatrisk')) },
    { key: 'ach-return', label: 'ACH return rate', display: `${achReturn.toFixed(1)}%`, level: clamp01(achReturn / 4) },
    { key: 'ach-exceptions', label: 'ACH exceptions', display: String(achExceptions), level: clamp01(achExceptions / 60) },
    { key: 'settlement-latency', label: 'Settlement latency (p99)', display: `${latency} ms`, level: clamp01(latency / 2600) },
    { key: 'duplicate-payments', label: 'Duplicate payments', display: String(duplicates), level: clamp01(duplicates / 26) },
    { key: 'dormant-reactivation', label: 'Dormant reactivations', display: String(dormant), level: clamp01(dormant / 30) },
    { key: 'cnp-velocity', label: 'Card-not-present flow', display: `${usd(cnp, 0)}/h`, level: clamp01(cnp / 44000) },
    { key: 'callback-failures', label: 'Callback failures', display: String(callbacks), level: clamp01(callbacks / 14) },
    { key: 'privileged-offwindow', label: 'Off-window privileged logins', display: String(offWindow), level: clamp01(offWindow / 9) },
    { key: 'mfa-failures', label: 'Failed MFA challenges', display: String(mfaFail), level: clamp01(mfaFail / 80) },
    { key: 'session-anomalies', label: 'Session anomalies', display: String(sessions), level: clamp01(sessions / 30) },
    { key: 'sanctions-hits', label: 'Sanctions screen hits', display: String(sanctions), level: clamp01(sanctions / 5) },
    { key: 'nsf-spike', label: 'NSF / overdraft delta', display: `+${nsf.toFixed(1)}%`, level: clamp01(nsf / 5.4) },
    { key: 'rate-sensitivity', label: 'Rate sensitivity (DV01)', display: `${rateSens} bps`, level: clamp01(rateSens / 300) },
    { key: 'lcr-shift', label: 'Liquidity coverage shift', display: `${lcr.toFixed(1)}%`, level: clamp01(lcr / 24) },
    { key: 'collateral-gap', label: 'Collateral valuation gap', display: `${collateral.toFixed(1)}%`, level: clamp01(collateral / 15) },
    { key: 'recon-breaks', label: 'Reconciliation breaks', display: String(recon), level: clamp01(recon / 42) },
  ];

  return rows.map((row) => ({ ...row, tone: tone(row.level) }));
}

/* -------------------------------------------------------------------------- */
/* ledger generation - exactly LEDGER_SIZE records across the real institutions */
/* -------------------------------------------------------------------------- */

function allocate(total: number, weights: number[], minimum: number): number[] {
  const sum = weights.reduce((a, b) => a + b, 0) || 1;
  const base = weights.map((w) => Math.max(minimum, Math.round((w / sum) * total)));
  let diff = total - base.reduce((a, b) => a + b, 0);
  // spread the rounding difference one record at a time
  let i = 0;
  while (diff !== 0 && i < base.length * 8) {
    const idx = i % base.length;
    if (diff > 0) {
      base[idx] += 1;
      diff -= 1;
    } else if (base[idx] > minimum) {
      base[idx] -= 1;
      diff += 1;
    }
    i += 1;
  }
  return base;
}

function buildLedger(institutions: FinancialInstitution[]): AnomalyRecord[] {
  const weights = institutions.map((i) => Math.log10(i.depositsUsd + 1) * (1 + i.countyCount / 40));
  const counts = allocate(LEDGER_SIZE, weights, 4);
  const records: AnomalyRecord[] = [];

  institutions.forEach((inst, index) => {
    const count = counts[index] ?? 0;
    for (let n = 0; n < count; n += 1) {
      const seed = `${inst.id}:${n}`;
      const archetype = ARCHETYPES[fnv1a(`${seed}:arch`) % ARCHETYPES.length];
      const title = pick(archetype.titles, `${seed}:title`);
      const severitySeed = fnv1a(`${seed}:sev`) % 6;
      const severity: Severity =
        severitySeed === 0 ? 'critical' : severitySeed <= 2 ? 'high' : 'medium';
      records.push({
        id: `${inst.id}-${n}`,
        institutionId: inst.id,
        institutionName: inst.name,
        severity,
        archetype: archetype.key,
        title,
        vector: archetype.vector,
        offsetMinutes: (fnv1a(`${seed}:age`) % 20160) + 1,
        systems: pickMany(archetype.systems, 3, `${seed}:sys`),
        logins: pickMany(archetype.logins, 2, `${seed}:login`),
        accounts: pickMany(archetype.accounts, 2, `${seed}:acct`),
        demo: true,
      });
    }
  });

  return records.sort((a, b) => a.offsetMinutes - b.offsetMinutes);
}

export const ANOMALY_LEDGER: AnomalyRecord[] = buildLedger(FINANCIAL_INSTITUTIONS);

export const LEDGER_BY_INSTITUTION: Map<string, AnomalyRecord[]> = (() => {
  const map = new Map<string, AnomalyRecord[]>();
  for (const record of ANOMALY_LEDGER) {
    const list = map.get(record.institutionId) ?? [];
    list.push(record);
    map.set(record.institutionId, list);
  }
  return map;
})();

export function anomaliesFor(institutionId: string): AnomalyRecord[] {
  return LEDGER_BY_INSTITUTION.get(institutionId) ?? [];
}

export const LEDGER_BAND_COLOR: Record<Severity, string> = {
  critical: '#f44336',
  high: '#ff9800',
  medium: '#ffd54f',
};

export function severityRank(severity: Severity): number {
  return severity === 'critical' ? 0 : severity === 'high' ? 1 : 2;
}

export function timeAgoLabel(minutes: number): string {
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 48) return `${hours}h ago`;
  return `${Math.floor(hours / 24)}d ago`;
}
